	"sap/fe/templates/ListReport/view/fragments/CollectionVisualization.fragment.xml":'<core:FragmentDefinition\n\txmlns="sap.fe.templates.controls"\n\txmlns:m="sap.m"\n\txmlns:core="sap.ui.core"\n\txmlns:contentSwitcher="sap.fe.macros.contentSwitcher"\n\txmlns:template="http://schemas.sap.com/sapui5/extension/sap.ui.core.template/1"\n\ttemplate:require="{\n\t\tCOMMON: \'sap/fe/macros/CommonHelper\'\n\t}"\n><template:if test="{= ${converterContext>hasMultiVisualizations} }"><template:then><m:VBox fitContainer="true" alignItems="Stretch" alignContent="Stretch" justifyContent="Start" renderType="Div"><template:repeat list="{converterContext>views}" var="view"><template:with path="view>primaryVisualization" var="presentationContext"><template:if test="{= ${view>contentSwitcherId}}"><template:then><contentSwitcher:ContentSwitcher id="{view>contentSwitcherId}" selectedKey="{pageInternal>alpContentView}"><template:if test="{= COMMON.isDesktop() }"><template:then><contentSwitcher:ContentSwitcherItem\n\t\t\t\t\t\t\t\t\t\t\t\ttext="{sap.fe.i18n>M_COMMON_HYBRID_SEGMENTED_BUTTON_ITEM_TOOLTIP}"\n\t\t\t\t\t\t\t\t\t\t\t\ticon="sap-icon://chart-table-view"\n\t\t\t\t\t\t\t\t\t\t\t\tkey="Hybrid"\n\t\t\t\t\t\t\t\t\t\t\t\tshowAll="true"\n\t\t\t\t\t\t\t\t\t\t\t/></template:then></template:if><contentSwitcher:ContentSwitcherItem\n\t\t\t\t\t\t\t\t\t\ttext="{sap.fe.i18n>M_COMMON_CHART_SEGMENTED_BUTTON_ITEM_TOOLTIP}"\n\t\t\t\t\t\t\t\t\t\ticon="sap-icon://bar-chart"\n\t\t\t\t\t\t\t\t\t\tkey="Chart"\n\t\t\t\t\t\t\t\t\t\tcontrolToSwitch="{view>chartControlId}::Chart"\n\t\t\t\t\t\t\t\t\t/><contentSwitcher:ContentSwitcherItem\n\t\t\t\t\t\t\t\t\t\ttext="{sap.fe.i18n>M_COMMON_TABLE_SEGMENTED_BUTTON_ITEM_TOOLTIP}"\n\t\t\t\t\t\t\t\t\t\ticon="sap-icon://table-view"\n\t\t\t\t\t\t\t\t\t\tkey="Table"\n\t\t\t\t\t\t\t\t\t\tcontrolToSwitch="{view>tableControlId}::Table"\n\t\t\t\t\t\t\t\t\t/></contentSwitcher:ContentSwitcher></template:then></template:if><template:repeat list="{presentationContext>visualizations}" var="visualizationDefinition"><m:MessageStrip\n\t\t\t\t\t\t\t\ttext="{= \'{parts:[{path:\\\'internal>controls/ignoredFields\' + (${visualizationDefinition>collection}) + (${visualizationDefinition>type}) + \'\\\'}, {value: \\\'\' + (${visualizationDefinition>type} === \'Chart\') + \'\\\'},{value: \' + (${visualizationDefinition>type} === \'Chart\' ? JSON.stringify(${visualizationDefinition>applySupported}) : \'\\\'\\\'\') + \'}], formatter: \\\'.formatters.setALPControlMessageStrip\\\'}\'}"\n\t\t\t\t\t\t\t\ttype="Information"\n\t\t\t\t\t\t\t\tshowIcon="true"\n\t\t\t\t\t\t\t\tshowCloseButton="true"\n\t\t\t\t\t\t\t\tclass="sapUiSmallMargin"\n\t\t\t\t\t\t\t\tvisible="{= \'{= (${internal>controls/ignoredFields\' + (${visualizationDefinition>collection}) + (${visualizationDefinition>type}) + \'} || []).length>0 &amp;&amp; ${pageInternal>alpContentView} !== \\\'Table\\\'}\' }"\n\t\t\t\t\t\t\t/><core:Fragment\n\t\t\t\t\t\t\t\tfragmentName="sap.fe.templates.ListReport.view.fragments.{visualizationDefinition>type}"\n\t\t\t\t\t\t\t\ttype="XML"\n\t\t\t\t\t\t\t/></template:repeat></template:with><template:with path="view>secondaryVisualization" var="presentationContext"><template:repeat list="{presentationContext>visualizations}" var="visualizationDefinition"><m:Text text="" class="sapUiSmallMarginTop" visible="{= ${pageInternal>alpContentView} === \'Hybrid\'}" /><m:HBox height="100%" width="100%" visible="{= ${pageInternal>alpContentView} !== \'Chart\'}"><core:Fragment\n\t\t\t\t\t\t\t\t\tfragmentName="sap.fe.templates.ListReport.view.fragments.{visualizationDefinition>type}"\n\t\t\t\t\t\t\t\t\ttype="XML"\n\t\t\t\t\t\t\t\t/></m:HBox></template:repeat></template:with></template:repeat></m:VBox></template:then><template:else><template:repeat list="{presentationContext>visualizations}" var="visualizationDefinition"><core:Fragment fragmentName="sap.fe.templates.ListReport.view.fragments.{visualizationDefinition>type}" type="XML" /></template:repeat></template:else></template:if></core:FragmentDefinition>\n',
